function normPaper(img){const k=Math.min(1,1024/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(8,Math.round(img.naturalWidth*k)),h=Math.max(8,Math.round(img.naturalHeight*k));
 const c=mk(w,h),x=c.getContext('2d');x.drawImage(img,0,0,w,h);const d=x.getImageData(0,0,w,h).data,L=new Float32Array(w*h),hist=new Uint32Array(256);
 for(let i=0;i<w*h;i++){const v=(d[i*4]+d[i*4+1]+d[i*4+2])/3;L[i]=v;hist[v|0]++}
 let acc=0,lo=0,hi=255;for(let v=0;v<256;v++){acc+=hist[v];if(acc>=w*h*.01){lo=v;break}}
 acc=0;for(let v=255;v>=0;v--){acc+=hist[v];if(acc>=w*h*.005){hi=v;break}}
 if(hi-lo<2)hi=lo+2;const V=new Uint8Array(w*h);for(let i=0;i<w*h;i++)V[i]=Math.max(0,Math.min(255,(L[i]-lo)/(hi-lo)*255));
 return{w:w,h:h,v:V}}
