async function exGIF(){
 const m=tmax(),spd=spdv();
 const ST=spd/30;let pos=[];   // 和视频同一条位置网格：视频每 1/30 秒正好走 ST 个 t
 for(let k=0;k<=Math.floor(m/ST+1e-9);k++)pos.push(k*ST);
 if(m-pos[pos.length-1]>1e-6)pos.push(m);   // 补上真正的终点，别停在倒数一格
 if(pos.length>400){const st=pos.length/400,p2=[];
  for(let k=0;k<400;k++)p2.push(pos[Math.min(pos.length-1,Math.round(k*st))]);
  p2[399]=m;pos=p2}
 const n=Math.max(2,pos.length);
 // 首尾各停 0.5s 用「一帧长延时」表示，不再铺 15 张一模一样的画面（体积白涨一大截）
 const dls=[50];
 for(let i=0;i<n;i++)dls.push(i%3===2?4:3);   // 3/4 交替，平均 3.33 个 1/100s = 30fps
 dls.push(140);   // 末尾多停 0.9s，和原来一致
 const tn=n+2;
 const sw=180,sh=Math.max(2,Math.round(sw*H/W)),sm=mk(sw,sh),xs=sm.getContext('2d');
 $('pmsg').textContent='正在分析颜色中…';$('pfill').style.width='4%';
 await new Promise(r=>setTimeout(r));
 const hist=new Map(),NS=Math.min(n,10);
 for(let s=0;s<NS;s++){
  const u=NS>1?s/(NS-1):0;t=rev?m*(1-u):m*u;draw();
  xs.clearRect(0,0,sw,sh);xs.drawImage(cv,0,0,sw,sh);
  const d=xs.getImageData(0,0,sw,sh).data;
  for(let q=0;q<d.length;q+=4){
   if(d[q+3]<128)continue;
   const k=((d[q]>>3)<<10)|((d[q+1]>>3)<<5)|(d[q+2]>>3);
   let e=hist.get(k);if(!e){e={n:0,r:0,g:0,b:0};hist.set(k,e)}
   e.n++;e.r+=d[q];e.g+=d[q+1];e.b+=d[q+2]}
  $('pfill').style.width=(4+(s+1)/NS*16).toFixed(0)+'%';
  await new Promise(r=>setTimeout(r))}
 const pal=medianCut([...hist.values()],255);
 const LUT=new Uint8Array(32768);
 for(let k=0;k<32768;k++){
  const r=((k>>10)&31)<<3,g=((k>>5)&31)<<3,b=(k&31)<<3;
  let best=1,bd=Infinity;
  for(let j=1;j<256;j++){const P=pal[j],dr=r-P[0],dg=g-P[1],db=b-P[2],d=dr*dr*.3+dg*dg*.59+db*db*.11;
   if(d<bd){bd=d;best=j}}
  LUT[k]=best}
 const BUD=inXhs()?1048576:Infinity;   // 只有容器要卡体积：writeTempFile 收 base64，配额撑不住大图；网页版直接下载，按原尺寸出
 let W2=640,H2=Math.max(2,Math.round(W2*H/W)),c2=mk(W2,H2),x2=c2.getContext('2d'),bytes;
 for(let pass=0;pass<4;pass++){
  if(c2.width!==W2)c2.width=W2;
  if(c2.height!==H2)c2.height=H2;
  x2.imageSmoothingQuality='high';
  $('pmsg').textContent=pass?'画面偏大，正在缩减尺寸…':'正在生成帧中…';
  const frames=[];
  for(let i=0;i<tn;i++){
   const qm=pos[i===0?0:(i===tn-1?n-1:i-1)];t=rev?m-qm:qm;draw();
   x2.clearRect(0,0,W2,H2);x2.drawImage(cv,0,0,W2,H2);
   const d=x2.getImageData(0,0,W2,H2).data,idx=new Uint8Array(W2*H2);
   for(let p=0,q=0;p<idx.length;p++,q+=4)
    idx[p]=d[q+3]<128?0:LUT[((d[q]>>3)<<10)|((d[q+1]>>3)<<5)|(d[q+2]>>3)];
   frames.push(idx);
   $('pfill').style.width=(20+(i+1)/tn*46).toFixed(0)+'%';
   if(i%2===1)await new Promise(r=>setTimeout(r))}
  $('pmsg').textContent='正在压缩中…';$('pfill').style.width='72%';
  await new Promise(r=>setTimeout(r));
  try{bytes=gifBytes(W2,H2,frames,dls,pal,EX.alpha)}
  catch(e){exfail('GIF 编码失败：'+e.message);return}
  if(!bytes.length){exfail('GIF 编码失败。');return}
  if(bytes.length<=BUD||W2<=160)break;
  const w1=Math.max(160,Math.round(W2*Math.sqrt(BUD/bytes.length)*.92));   // 缩小的收益比面积预测略差，留 8% 余量
  if(w1>=W2)break;
  W2=w1;H2=Math.max(2,Math.round(W2*H/W))}
 exsave(new Blob([bytes],{type:'image/gif'}),'gif')}
async function extract(){if(!vid)return;const n=Math.max(10,Math.min(200,+$('n').value||60)),d=vid.duration;
 playing=false;raw=[];busy(true,'正在抽帧中…');
 const vw=vid.videoWidth,vh=vid.videoHeight,asp=4/3,wide=vw/vh>asp,csw=wide?vh*asp:vw,csh=wide?vh:vw/asp,csx=(vw-csw)/2,csy=(vh-csh)/2,cw=520,ch=390;
 for(let k=0;k<n;k++){const p=new Promise(r=>vid.addEventListener('seeked',r,{once:true}));
  vid.currentTime=Math.min(Math.max(0,d-.05),(k+.5)/n*d);await p;
  const c=mk(cw,ch);c.getContext('2d').drawImage(vid,csx,csy,csw,csh,0,0,cw,ch);raw.push(c);
  if(k%4===3)await new Promise(r=>setTimeout(r))}
 t=0;$('scr').value=0;flt=null;FX.key='';if(fxKey())await refilter();else{build();busy(false)}}
function stash(){let d=$('vstash');if(d)return d;d=document.createElement('div');d.id='vstash';
 d.style.cssText='position:fixed;left:-9999px;top:0;width:320px;height:240px;overflow:hidden;pointer-events:none';
 document.body.appendChild(d);return d}
async function load(file){if(!file)return;setSrc('file');busy(true,'正在读取视频…');
 let v=document.createElement('video');v.muted=true;v.playsInline=true;v.preload='auto';
 stash().appendChild(v);              // 手机对不在文档里的 video 会拖着不加载，先挂到看不见的角落
 v.src=URL.createObjectURL(file);v.load();
 const t0=Date.now(),tick=setInterval(()=>{const s=Math.round((Date.now()-t0)/1000);
  busy(true,s>20?'正在读取视频… '+s+'s（视频可能在云端，或格式较重，请稍候）':'正在读取视频… '+s+'s')},500);
 await new Promise((r,j)=>{v.onloadeddata=r;v.onerror=()=>{$('st').textContent='无法读取该视频格式';j()}}).catch(()=>{v=null});
 clearInterval(tick);busy(false);
 if(!v){$('vname').textContent='读取失败，请换一个文件';$('vinfo').textContent='';return}
 vid=v;vid.className='vth';v.dataset.name=file.name;
 setSrc('file');clampV('n')}
function clampV(id){const el=$(id),hi=+el.max,lo=+el.min,v=''+Math.max(lo,Math.min(hi,+el.value||lo));
 if(v!==el.value){el.value=v;el.onchange&&el.onchange()}}   // 值没变就别再触发 onchange，否则 onchange→clampV 自己递归到爆栈
function bump(id,d){const el=$(id),hi=+el.max,lo=+el.min;
 el.value=Math.max(lo,Math.min(hi,(+el.value||lo)+d));el.oninput&&el.oninput();clampV(id)}
let IMP=null;
function openImp(){if($('imask').hidden)IMP={n:$('n').value,s:$('spd').value,vid:vid,src:SRC,pool:POOL};
 $('imask').hidden=false;setSrc(SRC)}
function closeImp(apply){
 if(!apply&&IMP){$('n').value=IMP.n;$('spd').value=IMP.s;
  if(vid&&vid.parentNode)vid.parentNode.removeChild(vid);
  vid=IMP.vid;POOL=IMP.pool;setSrc(IMP.src);updSpd()}
 IMP=null;$('imask').hidden=true}
$('f').onchange=e=>{const f=e.target.files[0];e.target.value='';openImp();if(f)load(f)};
$('imp').onclick=()=>openImp();
$('iclose').onclick=()=>closeImp(false);
$('imask').onclick=e=>{const E=e.target;if(E!==$('imask')||document.body.classList.contains('busy'))return;closeImp(false)};
$('igo').onclick=()=>{
 if(SRC==='cam'){if(!POOL||POOL.length<2){$('st').textContent='请先拍摄';return}
  const chgP=!IMP||IMP.pool!==POOL,chgN2=!IMP||IMP.n!==$('n').value;
  closeImp(true);if(cvMode)closeCv();
  if(chgP||chgN2)fromPool();else stat();return}
 if(!vid){$('st').textContent='请先添加视频';return}
 const chgV=!IMP||IMP.vid!==vid,chgN=!IMP||IMP.n!==$('n').value;
 closeImp(true);if(cvMode)closeCv();
 if(chgV||chgN)extract();else stat()};
$('nm').onclick=()=>bump('n',-5);$('np').onclick=()=>bump('n',5);
$('spm').onclick=()=>bump('spd',-1);$('spp').onclick=()=>bump('spd',1);
$('n').onchange=()=>clampV('n');
addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('imask').hidden)closeImp(false)});
addEventListener('dragover',e=>e.preventDefault());
addEventListener('drop',e=>{e.preventDefault();const f=e.dataTransfer.files[0];if(f){openImp();load(f)}});
// ---------- 相册 / 拍摄 ----------
let SRC='cam',POOL=null,POOLT=0;
// 池上限：满了就隔一帧丢一帧（时间分辨率减半，不停止录制），内存封顶约 110MB
const CAMMAX=140,CAMIV=80;
const CAM={on:false,stream:null,facing:'user',torch:false,timer:null,cdt:null,pool:[],tick:0,every:1,t0:0};
function refreshPick(){
 const box=$('vthbox');box.innerHTML='';
 const cam=SRC==='cam',ready=cam?(!!POOL&&POOL.length>1):!!vid,blocked=!cam&&inXhs();
 $('xhsgo').hidden=!blocked;
 if(blocked){$('vdrop').hidden=true;$('camdrop').hidden=true;$('vpick').hidden=true;
  $('prs').hidden=true;$('imhint').hidden=true;$('igo').disabled=true;return}
 if(ready&&cam){box.appendChild(POOL[0]);
  $('vname').textContent='摄像头拍摄';$('vinfo').textContent=POOL.length+' 帧 · '+POOLT.toFixed(1)+' 秒'}
 else if(ready){box.appendChild(vid);
  $('vname').textContent=vid.dataset.name||'视频';
  $('vinfo').textContent=vid.videoWidth+'×'+vid.videoHeight+(isFinite(vid.duration)?' · '+vid.duration.toFixed(1)+' 秒':'')}
 else{$('vname').textContent=cam?'摄像头拍摄':'视频';$('vinfo').textContent=cam?'还没拍':''}
 $('vdrop').hidden=!!cam||ready;$('camdrop').hidden=!cam||ready;$('vpick').hidden=!ready;
 $('prs').hidden=!ready;$('imhint').hidden=!!cam;
 $('imhint').textContent='建议使用 4:3 横版视频；其他比例会自动居中裁剪。';
 $('rpick').textContent=cam?'重拍':'替换';
 $('igo').disabled=!ready}
function setSrc(s){
 SRC=s;
 [].forEach.call($('isrc').querySelectorAll('input'),i=>{i.checked=(i.value===s)});
 refreshPick()}
function syncSrcUI(){
 const x=inXhs(),box=$('isrc'),L=box.children;
 const f=L[0].dataset.v==='file'?L[0]:L[1],c=L[0].dataset.v==='cam'?L[0]:L[1];
 if(x)box.insertBefore(c,f);else box.insertBefore(f,c);
 f.classList.toggle('off',x)}
$('isrc').onchange=e=>{if(e.target.name==='is')setSrc(e.target.value)};
$('rpick').onclick=e=>{if(SRC==='cam'){e.preventDefault();camOpen()}};
$('camdrop').onclick=()=>camOpen();
function camHint(t){$('camhint').textContent=t}
function camFit(){
 const g=$('campg');if(g.hidden)return;
 const h=(window.visualViewport&&window.visualViewport.height)||window.innerHeight||document.documentElement.clientHeight;
 $('camstage').style.maxWidth=Math.max(180,Math.min(g.clientWidth-32,Math.round((h-260)*4/3)))+'px'}
function camOpen(){
 document.body.classList.add('camon');
 $('campg').hidden=false;$('camcd').hidden=true;$('camrec').hidden=true;
 $('camstart').classList.remove('on');$('camflash').classList.toggle('on',CAM.torch);
 camHint('正在打开摄像头…');camFit();camStream()}
function camRelease(){
 document.body.classList.remove('camon');
 if(CAM.cdt){clearInterval(CAM.cdt);CAM.cdt=null}
 if(CAM.timer){clearInterval(CAM.timer);CAM.timer=null}
 CAM.on=false;
 if(CAM.stream){CAM.stream.getTracks().forEach(t=>t.stop());CAM.stream=null}
 const v=$('camv');if(v)v.srcObject=null}
function camClose(){camRelease();$('campg').hidden=true;refreshPick();
 $('st').textContent=POOL&&POOL.length>1?'已拍 '+POOL.length+' 帧 · '+POOLT.toFixed(1)+' 秒，点「完成」生成翻页书':''}
async function camStream(){
 if(!(navigator.mediaDevices&&navigator.mediaDevices.getUserMedia)){camHint('这个环境打不开摄像头。');return}
 if(CAM.stream){CAM.stream.getTracks().forEach(t=>t.stop());CAM.stream=null}
 try{CAM.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:CAM.facing,width:{ideal:1280},height:{ideal:960}},audio:false})}
 catch(err){camHint('打不开摄像头：'+((err&&err.name)||'未知')+'，请检查系统权限。');return}
 const v=$('camv');v.srcObject=CAM.stream;v.className=CAM.facing==='user'?'mir':'';
 const p=v.play&&v.play();if(p&&p.catch)p.catch(()=>{});
 if(CAM.torch)camTorch(true);
 camHint('按快门，3 秒倒计时后开始拍摄；再按一次停止。')}
function camTorch(on){
 CAM.torch=(typeof on==='boolean')?on:!CAM.torch;
 $('camflash').classList.toggle('on',CAM.torch);
 const tk=CAM.stream&&CAM.stream.getVideoTracks()[0];if(!tk)return;
 let caps=null;try{caps=tk.getCapabilities?tk.getCapabilities():null}catch(e){}
 if(caps&&!caps.torch){CAM.torch=false;$('camflash').classList.remove('on');camHint('这台设备的摄像头没有补光灯。');return}
 if(tk.applyConstraints)tk.applyConstraints({advanced:[{torch:CAM.torch}]}).catch(()=>{camHint('这台设备的摄像头没有补光灯。')})}
function camShutter(){
 if(CAM.on){camStopRec();return}
 if(!CAM.stream){camHint('摄像头还没准备好。');return}
 CAM.on=true;$('camstart').classList.add('on');$('camrec').hidden=true;
 let k=3;$('camcd').hidden=false;$('camcd').textContent=k;camHint('准备…');
 CAM.cdt=setInterval(()=>{k--;
  if(k>0){$('camcd').textContent=k;return}
  clearInterval(CAM.cdt);CAM.cdt=null;$('camcd').hidden=true;camRec()},1000)}
function camRec(){
 CAM.pool=[];CAM.tick=0;CAM.every=1;CAM.t0=Date.now();
 $('camcnt').textContent='0.0 秒';$('camrec').hidden=false;
 camHint('正在拍，再按一次快门停止。');
 if(CAM.timer)clearInterval(CAM.timer);CAM.timer=setInterval(camTick,CAMIV)}
function camTick(){
 CAM.tick++;
 if(CAM.tick%CAM.every)return;
 camGrab();
 if(CAM.pool.length>=CAMMAX){
  const a=[];for(let k=0;k<CAM.pool.length;k+=2)a.push(CAM.pool[k]);
  CAM.pool=a;CAM.every*=2}}
function camGrab(){
 $('camcnt').textContent=((Date.now()-CAM.t0)/1000).toFixed(1)+' 秒';
 const v=$('camv');if(!v.videoWidth)return;
 const vw=v.videoWidth,vh=v.videoHeight,asp=4/3,wide=vw/vh>asp,csw=wide?vh*asp:vw,csh=wide?vh:vw/asp;
 const c=mk(520,390),x=c.getContext('2d');
 if(CAM.facing==='user'){x.translate(520,0);x.scale(-1,1)}
 x.drawImage(v,(vw-csw)/2,(vh-csh)/2,csw,csh,0,0,520,390);
 CAM.pool.push(c)}
function camStopRec(){
 if(CAM.timer){clearInterval(CAM.timer);CAM.timer=null}
 if(CAM.cdt){clearInterval(CAM.cdt);CAM.cdt=null;$('camcd').hidden=true}
 CAM.on=false;$('camstart').classList.remove('on');$('camrec').hidden=true;
 if(CAM.pool.length<2){camHint('太短了，至少对着镜头停 1 秒。');return}
 POOL=CAM.pool;POOLT=(Date.now()-CAM.t0)/1000;
 camRelease();$('campg').hidden=true;refreshPick();
 $('st').textContent='拍好了：'+POOL.length+' 帧 · '+POOLT.toFixed(1)+' 秒，点「完成」生成翻页书'}
async function fromPool(){
 if(!POOL||POOL.length<2)return;
 const n=Math.max(10,Math.min(200,+$('n').value||60)),L=POOL.length;
 playing=false;raw=[];busy(true,'正在抽帧中…');
 for(let k=0;k<n;k++){
  raw.push(POOL[Math.round(k*(L-1)/(n-1))]);
  if(k%10===9)await new Promise(r=>setTimeout(r))}
 t=0;$('scr').value=0;flt=null;FX.key='';if(fxKey())await refilter();else{build();busy(false)}}
$('camclose').onclick=()=>camClose();
$('camstart').onclick=()=>camShutter();
$('camflash').onclick=()=>camTorch();
$('camflip').onclick=()=>{CAM.torch=false;$('camflash').classList.remove('on');
 CAM.facing=CAM.facing==='user'?'environment':'user';camStream()};
addEventListener('resize',()=>{if(!$('campg').hidden)camFit()});
addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('campg').hidden)camClose()});
// demo frames
for(let k=0;k<48;k++){const c=mk(320,180),x=c.getContext('2d'),q=k/48;
 const g=x.createLinearGradient(0,0,0,180);g.addColorStop(0,'hsl('+(200+q*60)+',55%,55%)');g.addColorStop(1,'hsl('+(30+q*40)+',70%,60%)');
 x.fillStyle=g;x.fillRect(0,0,320,180);x.fillStyle='#2a1d12';x.fillRect(0,140,320,40);
 const bx=30+q*260,by=140-Math.abs(Math.sin(q*Math.PI*4))*90;
 x.fillStyle='rgba(0,0,0,.3)';x.beginPath();x.ellipse(bx,146,16,4,0,0,7);x.fill();
 x.fillStyle='#fff3d6';x.beginPath();x.arc(bx,by-14,14,0,7);x.fill();raw.push(c)}
setCanvas();syncSrcUI();syncFmtUI();setSrc(SRC);build();if(fxKey())refilter();
